<?php // Shared form fields; the caller supplies the scoped action and CSRF token. ?>
<?php if ($browserSite): ?><label class="u-block u-mb10"><input type="checkbox" name="inherit_browser_cache" value="1" <?= $site['browser_cache_override'] === null ? 'checked' : '' ?> title="Use central defaults, including future administrator changes. Uncheck to save settings only for this domain and its aliases."> Use central defaults</label><?php endif; ?>
<label class="u-block u-mb10"><input type="checkbox" name="browser_enabled" value="1" <?= !empty($browserChoice['enabled']) ? 'checked' : '' ?> title="Add browser Cache-Control headers to successful static-file responses. Disabling removes these addon headers; it does not disable Varnish."> Set browser cache headers</label>
<label class="form-label" for="static-<?= $escape($browserId) ?>">Ordinary files · seconds</label>
<input class="form-control u-mb10" id="static-<?= $escape($browserId) ?>" name="static_seconds" type="number" min="0" step="1" value="<?= $escape($browserChoice['static_seconds'] ?? 2592000) ?>" title="Browser lifetime of ordinary files served directly from disk. Default 2592000 seconds = 30 days. Zero requests revalidation. Changing a file at the same URL does not clear copies already in visitors’ browsers." required>
<label class="form-label" for="versioned-<?= $escape($browserId) ?>">Content-versioned files · seconds</label>
<input class="form-control u-mb10" id="versioned-<?= $escape($browserId) ?>" name="versioned_seconds" type="number" min="0" step="1" value="<?= $escape($browserChoice['versioned_seconds'] ?? 31536000) ?>" title="Lifetime for declared paths whose content hash changes with the file. Default one year, immutable. Zero requests revalidation. A query parameter alone does not declare a file immutable." required>
<label class="form-label" for="paths-<?= $escape($browserId) ?>">Additional content-versioned paths</label>
<textarea class="form-control u-mb10" id="paths-<?= $escape($browserId) ?>" name="versioned_paths" rows="3" spellcheck="false" placeholder="/assets/app-{hash}.js" title="One absolute URL path per line. Use {hash} for a hexadecimal content fingerprint and * within a path segment. Declare only files renamed when their content changes. The UltraCache profile adds its CSS-bundle pattern automatically."><?= $escape(implode("\n", $browserSite ? ($site['browser_cache_override']['versioned_paths'] ?? $browserChoice['versioned_paths'] ?? []) : ($browserChoice['versioned_paths'] ?? []))) ?></textarea>
<p class="u-mb10">Nginx still serves existing static files directly. These settings do not change HTML cache lifetimes in Varnish. UltraCache CSS bundles receive their profile preset automatically.</p>
<button class="button" type="submit" title="Apply browser headers without restarting Varnish or clearing its HTML cache. Existing browser copies retain the lifetime sent when they were downloaded.">Apply browser cache</button>
